frappe.ui.form.on('iWEXClock Reminder', {
    onload: function(frm) {
        if (frm.is_new()) {  // only when creating a new Reminder
            frappe.db.get_value('iWEXClock Reminder Settings',
                { user: frappe.session.user },
                ['notification_sound', 'volume']
            ).then(r => {
                if (r && r.message) {
                    // If user has settings → use them
                    if (r.message.notification_sound) {
                        frm.set_value('notification_sound', r.message.notification_sound);
                    } else {
                        frm.set_value('notification_sound', "Default");
                    }

                    if (r.message.volume) {
                        frm.set_value('volume', r.message.volume);
                    } else {
                        frm.set_value('volume', 50);
                    }
                } else {
                    // No Reminder Settings found for this user → use defaults
                    frm.set_value('notification_sound', "Default");
                    frm.set_value('volume', 50);
                }
            });
        }
    }
});

frappe.ui.form.on('iWEXClock Reminder', {
	validate: function(frm) {
        if (frm.doc.volume < 1 || frm.doc.volume > 100) {
            frappe.throw(__("Volume must be between 1 and 100"));
        }
    }
});

frappe.ui.form.on('iWEXClock Reminder Settings', {
		validate: function(frm) {
        if (frm.doc.volume < 1 || frm.doc.volume > 100) {
            frappe.throw(__("Volume must be between 1 and 100"));
        }
    }
});

frappe.ui.form.on('iWEXClock Reminder', {
	refresh(frm) {
	frm.add_custom_button("Reminder Settings", () => {
            frappe.set_route("List", "iWEXClock Reminder Settings");
        });
	}
})

frappe.ui.form.on('iWEXClock Reminder', {
    onload: function(frm) {
        update_start_time(frm);
    },
    start_time: function(frm) {
        update_start_time(frm);
    },
    disable_rounding: function(frm) {
        frm.set_value('start_time', '');
    }

});

function update_start_time(frm){
    if (!frm.doc.start_time) return;
     if (frm.doc.disable_rounding == 1) {

            return;
        } 

            let parts = frm.doc.start_time.split(":");
            let hours = parseInt(parts[0]);
            let minutes = parseInt(parts[1]);
            let seconds = parseInt(parts[2] || "0");

            if (minutes < 15) {
                minutes = 0;
            } else if (minutes < 45) {
                minutes = 30;
            } else {
                minutes = 0;
                hours++;
                if (hours == 24) hours = 0; // wrap around midnight
            }

            let hh = String(hours).padStart(2, '0');
            let mm = String(minutes).padStart(2, '0');
            let ss = "00";

            // This will update it on the form immediately
            frm.set_value('start_time', `${hh}:${mm}:${ss}`);
        }

// Client Script for iWEXClock Reminder DocType
// This script automatically updates the Title field by concatenating
// sub_type and frequency values when either field changes

frappe.ui.form.on('iWEXClock Reminder', {
    // Trigger when sub_type field changes
    sub_type: function(frm) {
        update_title(frm);
    },

    // Trigger when frequency field changes
    frequency: function(frm) {
        update_title(frm);
    }
});

// Function to concatenate sub_type and frequency into title
function update_title(frm) {
    let sub_type = frm.doc.sub_type || '';
    let frequency = frm.doc.frequency || '';


    // Only concatenate if both fields have values
    if (sub_type && frequency) {
        let title = sub_type + ' - ' + frequency;
        frm.set_value('title', title);
    } else if (sub_type) {
        // If only sub_type is set, use just that
        frm.set_value('title', sub_type);
    } else if (frequency) {
        // If only frequency is set, use just that
        frm.set_value('title', frequency);
    } else {
        // If both are empty, clear the title
        frm.set_value('title', '');
    }
}
